var REFRESH_INTERVAL_MS = 1000;
async function showStatusDialog(pi, ctx, deps) {
  const sessionId = resolveSessionId(ctx);
  if (!sessionId)
    throw new Error("No active Pi session is available.");
  await ctx.ui.custom((tui, theme, _keybindings, done) => new StatusDialogComponent({
    pi,
    ctx,
    deps,
    sessionId,
    theme,
    tui,
    done
  }), {
    overlay: true,
    overlayOptions: { anchor: "center", width: 78 }
  });
}

class StatusDialogComponent {
  props;
  detail;
  refreshTimer = null;
  closed = false;
  constructor(props) {
    this.props = props;
    this.detail = buildPiStatusDetail(props.pi, props.ctx, props.deps, props.sessionId);
    this.refreshTimer = setInterval(() => {
      if (this.closed)
        return;
      try {
        this.detail = buildPiStatusDetail(this.props.pi, this.props.ctx, this.props.deps, this.props.sessionId);
        this.props.tui.requestRender();
      } catch {}
    }, REFRESH_INTERVAL_MS);
  }
  handleInput(data) {
    if (matchesKey(data, "escape") || matchesKey(data, "ctrl+c") || matchesKey(data, "return")) {
      this.close();
    }
  }
  close() {
    if (this.closed)
      return;
    this.closed = true;
    if (this.refreshTimer) {
      clearInterval(this.refreshTimer);
      this.refreshTimer = null;
    }
    this.props.done(undefined);
  }
  invalidate() {}
  render(width) {
    const innerWidth = Math.max(20, width - 4);
    const inner = renderInner(this.detail, this.props.theme, innerWidth);
    return drawBorder(inner, width, this.props.theme);
  }
  dispose() {
    if (this.refreshTimer) {
      clearInterval(this.refreshTimer);
      this.refreshTimer = null;
    }
  }
}
