// packages/hepi-basics/src/rtk/rtk/output-metrics.ts
function createOutputMetrics() {
  const records = [];
  return {
    track(original, filtered, tool, techniques) {
      const originalChars = original.length;
      const filteredChars = filtered.length;
      const savingsPercent = originalChars > 0 ? Math.round((originalChars - filteredChars) / originalChars * 100 * 100) / 100 : 0;
      const record3 = {
        timestamp: new Date().toISOString(),
        tool,
        techniques: techniques.join(",") || "none",
        originalChars,
        filteredChars,
        savingsPercent
      };
      records.push(record3);
      return record3;
    },
    clear() {
      records.length = 0;
    },
    summary() {
      if (records.length === 0)
        return "RTK output compaction metrics: no data yet.";
      const totalOriginal = records.reduce((sum, metric) => sum + metric.originalChars, 0);
      const totalFiltered = records.reduce((sum, metric) => sum + metric.filteredChars, 0);
      const totalSaved = totalOriginal - totalFiltered;
      const savingsPercent = totalOriginal > 0 ? totalSaved / totalOriginal * 100 : 0;
      const byTool = new Map;
      for (const metric of records) {
        const existing = byTool.get(metric.tool) ?? {
          count: 0,
          originalChars: 0,
          filteredChars: 0
        };
        existing.count += 1;
        existing.originalChars += metric.originalChars;
        existing.filteredChars += metric.filteredChars;
        byTool.set(metric.tool, existing);
      }
      let result = `RTK output compaction metrics
`;
      result += `calls=${records.length}, saved=${totalSaved.toLocaleString()} chars (${savingsPercent.toFixed(1)}%)
`;
      for (const [tool, stats] of byTool) {
        const toolSaved = stats.originalChars - stats.filteredChars;
        const toolSavingsPercent = stats.originalChars > 0 ? toolSaved / stats.originalChars * 100 : 0;
        result += `- ${tool}: ${stats.count} calls, saved ${toolSaved.toLocaleString()} chars (${toolSavingsPercent.toFixed(1)}%)
`;
      }
      return result.trimEnd();
    }
  };
}
var defaultOutputMetrics = createOutputMetrics();
