function hasConfiguredPackage(settings2, candidates) {
  if (typeof settings2 !== "object" || settings2 === null || Array.isArray(settings2))
    return false;
  if (!("packages" in settings2) || !Array.isArray(settings2.packages))
    return false;
  return settings2.packages.some((packageName) => typeof packageName === "string" && candidates.some((candidate) => {
    const normalized = packageName.startsWith("npm:") ? packageName.slice("npm:".length) : packageName;
    return normalized === candidate || normalized.startsWith(`${candidate}@`);
  }));
}

