function registerHepiFff(pi2, options = {}) {
  let runtime;
  let enabledFeatures = new Set(ALL_FEATURE_KEYS);
  const autocompleteContexts = new WeakSet;
  const initialFeatureState = loadGlobalFeatureStateSync();
  if (initialFeatureState.isOk())
    enabledFeatures = new Set(initialFeatureState.value ?? ALL_FEATURE_KEYS);
  else
    console.warn("Failed to restore HEPI FFF feature state during extension load:", initialFeatureState.error);
  const isFeatureEnabled = (feature) => enabledFeatures.has(feature);
  const getRuntime = () => runtime ?? null;
  const getEnabledFeatures = () => new Set(enabledFeatures);
  const applyUiConfiguration = (ctx) => {
    if (isFeatureEnabled("autocomplete") && !autocompleteContexts.has(ctx)) {
      autocompleteContexts.add(ctx);
      ctx.ui.addAutocompleteProvider((baseProvider) => createFffAutocompleteProvider(baseProvider, () => runtime, () => isFeatureEnabled("autocomplete")));
    }
  };
  const persistFeatures = async (next) => {
    const saved = await saveGlobalFeatureState(next);
    if (saved.isErr())
      console.error("Failed to save HEPI FFF feature state:", saved.error);
  };
  const agentToolsDisabledText = () => 'HEPI FFF feature "agent tools" is disabled. Use /fff-features to re-enable it.';
  registerTools(pi2, {
    getRuntime,
    isFeatureEnabled,
    agentToolsDisabledText
  }, options);
  registerCommands(pi2, {
    getRuntime,
    isFeatureEnabled,
    getEnabledFeatures,
    persistFeatures
  });
  const lifecycle = new HepiLifecycleController({
    onStart: async (session) => {
      runtime?.dispose();
      runtime = new FffRuntime(session.ctx.cwd);
      const activeRuntime = runtime;
      session.registry.registerLifecycle({
        id: "fff-runtime",
        cleanup: () => {
          activeRuntime.dispose();
          if (runtime === activeRuntime)
            runtime = undefined;
        }
      });
      applyUiConfiguration(session.ctx);
      (async () => {
        const warmed = await activeRuntime.warm(1500);
        if (runtime !== activeRuntime)
          return;
        if (warmed.isErr()) {
          if (isFeatureEnabled("statusUI"))
            session.ctx.ui.notify(`fff unavailable: ${warmed.error.message}`, "warning");
          return;
        }
        if (isFeatureEnabled("statusUI")) {
          const indexed = warmed.value.indexedFiles ? ` (${warmed.value.indexedFiles} files)` : "";
          session.ctx.ui.notify(`fff path + grep mode enabled${indexed}`, "info");
        }
      })();
    }
  });
  registerHepiLifecycle(pi2, lifecycle, "pi-fff");
}

